@pytest.mark.parametrize(
    "surface,values,expected_parts",
    HOSTILE_SECTIONS_CASES.values(),
    ids=HOSTILE_SECTIONS_CASES,
)
def test_hostile_sections(surface, values, expected_parts):
    member = finding(**values)
    if surface == "group":
        body = compose.render_group_body(member, [finding(title="Other", body="b")])
    else:
        body = compose.compose_review_body(
            "",
            [[compose.SkippedEntry(member["file"], values.get("line", 99), member)]],
            platform="github",
            findings_count=1,
            sha="a" * 40,
        ).body
    for expected in expected_parts:
        assert expected in body
    assert "<!-- code-gauntlet-finding-key:" not in body
    assert open_fence(body) is None
    if surface != "skipped":
        assert body.endswith(TRAILER)


